#!/usr/bin/env node
'use strict';

/**
 * Re-tag existing Document History rows as Manual or Automation.
 *
 * The code fix stops NEW rows being mislabelled, but the rows already in the
 * database were written under the old rule — `/auto|system|cron/i` against
 * `sentBy` — which read the placeholder "System" as "a cron did this". That is
 * why every line in the HR portal's Document History reads "Automation",
 * including documents an HR user generated by hand.
 *
 * This re-derives `method` for every row using the same helper the server now
 * uses (DocumentHistory.resolveMethod), so old rows and new rows agree.
 *
 * Rows whose `sentBy` is the bare placeholder "System" are the ambiguous ones —
 * the value records that nobody wrote down who did it. They are counted and
 * reported separately, and under the new rule they become Manual, because a
 * document produced through the portal without a scheduled job crediting
 * itself was made by a person.
 *
 * Dry run by default.
 *
 *   node scripts/reclassify-document-history-method.js
 *   node scripts/reclassify-document-history-method.js --apply
 */

require('dotenv').config();
const mongoose = require('mongoose');

const APPLY = process.argv.includes('--apply');

async function main() {
  const uri = process.env.MONGODB_URI;
  if (!uri) {
    console.error('MONGODB_URI is not set. Run this on the server, where .env is.');
    process.exit(1);
  }

  await mongoose.connect(uri);
  console.log(`Connected. Mode: ${APPLY ? 'APPLY' : 'DRY RUN'}\n`);

  const DocumentHistory = require('../models/DocumentHistory');

  const rows = await DocumentHistory.find({})
    .select('_id sentBy method documentType documentNumber').lean();

  console.log(`Document History rows: ${rows.length}`);

  let toManual = 0;
  let toAutomation = 0;
  let unchanged = 0;
  let ambiguous = 0;
  const bySentBy = new Map();

  const updates = [];
  for (const row of rows) {
    const sentBy = row.sentBy || '';
    // Deliberately ignores the stored method: it is the value that is wrong.
    const correct = DocumentHistory.resolveMethod(undefined, sentBy);

    if (/^system$/i.test(sentBy.trim())) ambiguous++;
    bySentBy.set(sentBy || '(blank)', (bySentBy.get(sentBy || '(blank)') || 0) + 1);

    if (row.method === correct) { unchanged++; continue; }
    if (correct === 'manual') toManual++; else toAutomation++;
    updates.push({ _id: row._id, method: correct });
  }

  console.log(`  → already correct     : ${unchanged}`);
  console.log(`  → retag as Manual     : ${toManual}`);
  console.log(`  → retag as Automation : ${toAutomation}`);
  console.log(`  → of those, sentBy is the ambiguous placeholder "System": ${ambiguous}\n`);

  console.log('sentBy values found:');
  [...bySentBy.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, 25)
    .forEach(([who, n]) => console.log(`  ${String(n).padStart(6)}  ${who}`));

  if (!updates.length) {
    console.log('\nNothing to change.');
  } else if (APPLY) {
    const ops = updates.map((u) => ({
      updateOne: { filter: { _id: u._id }, update: { $set: { method: u.method } } }
    }));
    // Chunked so a very large history does not build one enormous batch.
    for (let i = 0; i < ops.length; i += 500) {
      await DocumentHistory.bulkWrite(ops.slice(i, i + 500));
    }
    console.log(`\nUpdated ${updates.length} rows.`);
  } else {
    console.log(`\nNothing was written. Re-run with --apply to retag ${updates.length} rows.`);
  }

  await mongoose.disconnect();
}

main().catch((err) => {
  console.error('Reclassification failed:', err.message);
  process.exit(1);
});
